"use strict";
eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   attractionsTranslations: () => (/* binding */ attractionsTranslations)\n/* harmony export */ });\nconst attractionsTranslations = {\n    \"attractions.title\": {\n        en: \"Explore Bosnia's Beauty\",\n        bs: \"Istražite ljepote Bosne\",\n        ar: \"اكتشف جمال البوسنة\"\n    },\n    \"attractions.subtitle\": {\n        en: \"Discover the stunning natural and cultural sites across Bosnia and Herzegovina\",\n        bs: \"Otkrijte zadivljujuća prirodna i kulturna mjesta širom Bosne i Hercegovine\",\n        ar: \"اكتشف المواقع الطبيعية والثقافية المذهلة في جميع أنحاء البوسنة والهرسك\"\n    },\n    \"attractions.sarajevo.title\": {\n        en: \"Old Bridge in Mostar\",\n        bs: \"Stari most u Mostaru\",\n        ar: \"الجسر القديم في موستار\"\n    },\n    \"attractions.sarajevo.location\": {\n        en: \"Mostar\",\n        bs: \"Mostar\",\n        ar: \"موستار\"\n    },\n    \"attractions.sarajevo.description\": {\n        en: \"One of Bosnia's most recognizable landmarks, the Old Bridge (Stari Most) is a 16th-century Ottoman bridge that crosses the river Neretva. The bridge was destroyed in 1993 during the Bosnian War but was later rebuilt and opened in 2004.\",\n        bs: \"Jedan od najprepoznatljivijih bosanskih znamenitosti, Stari most je osmanski most iz 16. vijeka koji prelazi rijeku Neretvu. Most je uništen 1993. godine tokom rata u Bosni, ali je kasnije obnovljen i otvoren 2004. godine.\",\n        ar: \"أحد أشهر المعالم في البوسنة، الجسر القديم (ستاري موست) هو جسر عثماني من القرن السادس عشر يعبر نهر نيريتفا. تم تدمير الجسر عام 1993 خلال حرب البوسنة ولكن تمت إعادة بنائه لاحقًا وافتتاحه في عام 2004.\"\n    },\n    \"attractions.mostar.title\": {\n        en: \"Baščaršija\",\n        bs: \"Baščaršija\",\n        ar: \"باشتشارشيا\"\n    },\n    \"attractions.mostar.location\": {\n        en: \"Sarajevo\",\n        bs: \"Sarajevo\",\n        ar: \"سراييفو\"\n    },\n    \"attractions.mostar.description\": {\n        en: \"The historical and cultural center of Sarajevo, Baščaršija was built in the 15th century when Isa-Beg Isaković founded the town. The word Baščaršija derives from the Turkish language and means 'main market'.\",\n        bs: \"Historijski i kulturni centar Sarajeva, Baščaršija je izgrađena u 15. vijeku kada je Isa-beg Isaković osnovao grad. Riječ Baščaršija potiče iz turskog jezika i znači 'glavna čaršija'.\",\n        ar: \"المركز التاريخي والثقافي لسراييفو، تم بناء باشتشارشيا في القرن الخامس عشر عندما أسس عيسى بيك إيساكوفيتش المدينة. كلمة باشتشارشيا مشتقة من اللغة التركية وتعني 'السوق الرئيسي'.\"\n    },\n    \"attractions.jajce.title\": {\n        en: \"Jajce Waterfall\",\n        bs: \"Vodopad Jajce\",\n        ar: \"شلال يايتسه\"\n    },\n    \"attractions.jajce.location\": {\n        en: \"Jajce\",\n        bs: \"Jajce\",\n        ar: \"يايتسه\"\n    },\n    \"attractions.jajce.description\": {\n        en: \"A beautiful 17-meter high waterfall where the Pliva River meets the Vrbas in the heart of the historic town of Jajce. It's one of the only waterfalls in the world located in the center of a town.\",\n        bs: \"Prelijepi vodopad visok 17 metara gdje se rijeka Pliva sastaje sa Vrbasom u srcu historijskog grada Jajce. To je jedan od rijetkih vodopada na svijetu koji se nalazi u centru grada.\",\n        ar: \"شلال جميل بارتفاع 17 مترًا حيث يلتقي نهر بليفا مع فرباس في قلب مدينة يايتسه التاريخية. إنه أحد الشلالات الوحيدة في العالم الموجودة في وسط المدينة.\"\n    },\n    \"attractions.mountain.title\": {\n        en: \"Mountain Landscapes\",\n        bs: \"Planinski krajolici\",\n        ar: \"المناظر الجبلية\"\n    },\n    \"attractions.mountain.location\": {\n        en: \"Bjelašnica\",\n        bs: \"Bjelašnica\",\n        ar: \"بيلاشنيتسا\"\n    },\n    \"attractions.mountain.description\": {\n        en: \"Bosnia and Herzegovina features stunning mountain landscapes with pristine nature and excellent opportunities for hiking, skiing, and outdoor adventures.\",\n        bs: \"Bosna i Hercegovina se odlikuje zadivljujućim planinski krajolicima s netaknutom prirodom i odličnim mogućnostima za planinarenje, skijanje i avanture na otvorenom.\",\n        ar: \"تتميز البوسنة والهرسك بمناظر جبلية خلابة مع طبيعة بكر وفرص ممتازة للمشي والتزلج والمغامرات في الهواء الطلق.\"\n    },\n    \"attractions.river.title\": {\n        en: \"Una River\",\n        bs: \"Rijeka Una\",\n        ar: \"نهر أونا\"\n    },\n    \"attractions.river.location\": {\n        en: \"Una National Park\",\n        bs: \"Nacionalni park Una\",\n        ar: \"حديقة أونا الوطنية\"\n    },\n    \"attractions.river.description\": {\n        en: \"The Una River is known for its crystal clear emerald waters and breathtaking waterfalls, offering exceptional rafting and nature experiences.\",\n        bs: \"Rijeka Una je poznata po svojim kristalno čistim smaragdnim vodama i zadivljujućim vodopadima, pružajući izuzetna iskustva raftinga i prirode.\",\n        ar: \"يشتهر نهر أونا بمياهه الزمردية الصافية والشلالات الخلابة، مما يوفر تجارب استثنائية للتجديف والطبيعة.\"\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/translations/attractions.translations.ts\n");

